import{c as a,Q as t,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"BudgetThinker: Empowering Budget-aware LLM Reasoning with Control Tokens","description":"","frontmatter":{"url":"https://arxiv.org/abs/2508.17196","title":"BudgetThinker: Empowering Budget-aware LLM Reasoning with Control Tokens","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2508.17196,"authors":["Hao Wen","Xinrui Wu","Yi Sun","Feifei Zhang","Liye Chen","Jie Wang","Yunxin Liu","Yunhao Liu","Ya-Qin Zhang","Yuanchun Li"],"domains":["cs.LG","cs.AI"],"html":"https://arxiv.org/html/2508.17196v1","pdf_path":"pdfs/2508.17196.pdf","published_date":"2025-08-24T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-08-24-budgetthinker-budget-aware-reasoning-control-tokens-2508-17196.md","filePath":"research/papers/2025-08-24-budgetthinker-budget-aware-reasoning-control-tokens-2508-17196.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-08-24-budgetthinker-budget-aware-reasoning-control-tokens-2508-17196.md"};function o(s,e,l,h,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="budgetthinker-empowering-budget-aware-llm-reasoning-with-control-tokens" tabindex="-1">BudgetThinker: Empowering Budget-aware LLM Reasoning with Control Tokens <a class="header-anchor" href="#budgetthinker-empowering-budget-aware-llm-reasoning-with-control-tokens" aria-label="Permalink to &quot;BudgetThinker: Empowering Budget-aware LLM Reasoning with Control Tokens&quot;">​</a></h1><p><strong>Authors</strong>: Hao Wen, Xinrui Wu, Yi Sun, Feifei Zhang, Liye Chen, Jie Wang, Yunxin Liu, Yunhao Liu, Ya-Qin Zhang, Yuanchun Li <strong>Published</strong>: August 24, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2508.17196" target="_blank" rel="noreferrer">https://arxiv.org/abs/2508.17196</a> · <a href="https://arxiv.org/html/2508.17196v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2508.17196 <strong>Categories</strong>: cs.LG, cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2508.17196" target="_blank" rel="noreferrer">research/papers/pdfs/2508.17196.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Recent advancements in Large Language Models (LLMs) have leveraged increased test-time computation to enhance reasoning capabilities, a strategy that, while effective, incurs significant latency and resource costs, limiting their applicability in real-world time-constrained or cost-sensitive scenarios. This paper introduces BudgetThinker, a novel framework designed to empower LLMs with budget-aware reasoning, enabling precise control over the length of their thought processes. We propose a methodology that periodically inserts special control tokens during inference to continuously inform the model of its remaining token budget. This approach is coupled with a comprehensive two-stage training pipeline, beginning with Supervised Fine-Tuning (SFT) to familiarize the model with budget constraints, followed by a curriculum-based Reinforcement Learning (RL) phase that utilizes a length-aware reward function to optimize for both accuracy and budget adherence. We demonstrate that BudgetThinker significantly surpasses strong baselines in maintaining performance across a variety of reasoning budgets on challenging mathematical benchmarks. Our method provides a scalable and effective solution for developing efficient and controllable LLM reasoning, making advanced models more practical for deployment in resource-constrained and real-time environments.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>推理中週期性插入 control token 持續告知模型「剩餘 token budget」——把 budget 從 prompt 一次性提示升級為 inference 過程中的持續信號</li><li>兩階段訓練：SFT 熟悉 budget 約束 → curriculum RL（length-aware reward）同時優化 accuracy 與 budget adherence</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>數學 benchmark 上跨多種 reasoning budget 均顯著優於 strong baselines；具體數字未取得（abstract 未含）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>需訓練介入（SFT+RL），閉源 API 模型無法直接套用</li><li>驗證集中於數學推理，agent/長文任務泛化未報</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>與 2412.18547 構成 token budget 研究線的 prompt 端 vs 訓練端對照；對 <code>.claude/skills/output-compress</code> 而言可落地的僅「持續回饋剩餘預算」的介面概念（如 checkpoint 中注入剩餘 budget 提示）。</li><li>「budget adherence 用機械 reward 驗證而非模型自報」與機械失真閘的零 LLM 自評原則同構。⚠️ 方法本體屬訓練側，workspace 不落地。</li></ul>',16)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
